function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const row = $json;

const sourceFactsText = [safeStr(row.title), safeStr(row.summaryText), safeStr(row.combinedText)]
  .filter(Boolean).join('\n\n').slice(0, 6000);

return {
  json: {
    vorgangKey: safeStr(row.vorgangKey),
    vorgangsnummer: safeStr(row.vorgangsnummer),
    title: safeStr(row.title),
    sourceFactsText: sourceFactsText
  }
};

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function asArr(v) { return Array.isArray(v) ? v.filter(Boolean).map(safeStr) : []; }

function getAiText(j) {
  if (typeof j.content === 'string') return j.content;
  if (typeof j.text === 'string') return j.text;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) return safeStr(j.choices[0].message.content);
  if (Array.isArray(j.output)) {
    const msg = j.output.find(function(o) { return o && o.type === 'message' && Array.isArray(o.content); });
    const part = msg && msg.content.find(function(c) { return c && typeof c.text === 'string'; });
    if (part) return part.text;
  }
  return safeStr(JSON.stringify(j));
}

function __repairJsonText(text) {
  // Repairs two recurring AI-JSON breakage patterns (found live 2026-07-26 on
  // Vorgang 2026/105's P3 analysis): (1) the model forgets to close a string
  // value and just continues with a raw newline into the next "key": pattern,
  // (2) the model emits a stray extra closing bracket/brace. Only touches
  // content while tracking whether we're inside a string, so legitimate
  // structural whitespace outside strings is left untouched.
  var out = [];
  var inString = false, escaped = false;
  for (var i = 0; i < text.length; i++) {
    var ch = text[i];
    if (inString) {
      if (escaped) { out.push(ch); escaped = false; continue; }
      if (ch === '\\') { out.push(ch); escaped = true; continue; }
      if (ch === '"') { out.push(ch); inString = false; continue; }
      if (ch === '\n' || ch === '\r') {
        var rest = text.slice(i);
        var m = /^[\r\n]+\s*"[A-Za-z_][A-Za-z0-9_]*"\s*:/.exec(rest);
        if (m) {
          out.push('",'); inString = false; i += 1;
          while (i < text.length && (text[i] === '\r' || text[i] === '\n')) i++;
          i -= 1;
          continue;
        }
        out.push(ch === '\n' ? '\\n' : '\\r');
        continue;
      }
      if (ch === '\t') { out.push('\\t'); continue; }
      out.push(ch);
    } else {
      if (ch === '"') inString = true;
      out.push(ch);
    }
  }
  var stage1 = out.join('');

  var out2 = [];
  var stack = [];
  inString = false; escaped = false;
  var pairs = { '}': '{', ']': '[' };
  for (var j = 0; j < stage1.length; j++) {
    var c = stage1[j];
    if (inString) {
      out2.push(c);
      if (escaped) { escaped = false; }
      else if (c === '\\') { escaped = true; }
      else if (c === '"') { inString = false; }
      continue;
    }
    if (c === '"') { inString = true; out2.push(c); continue; }
    if (c === '{' || c === '[') { stack.push(c); out2.push(c); continue; }
    if (c === '}' || c === ']') {
      if (stack.length && stack[stack.length - 1] === pairs[c]) { stack.pop(); out2.push(c); }
      continue;
    }
    out2.push(c);
  }
  return out2.join('');
}

function __robustJsonParse(raw) {
  try {
    return JSON.parse(raw);
  } catch (e1) {
    try {
      return JSON.parse(__repairJsonText(raw));
    } catch (e2) {
      throw e1;
    }
  }
}

function extractJson(text) {
  const t = safeStr(text).replace(/```json/gi, '```').replace(/```/g, '');
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return null;
  try { return __robustJsonParse(t.substring(start, end + 1)); } catch (e) { return null; }
}

const base = $('Normalisiere Eingabe').item.json;
const aiText = getAiText($json);
const parsed = extractJson(aiText);

if (!parsed) {
  return {
    json: {
      vorgangKey: base.vorgangKey,
      vorgangsnummer: base.vorgangsnummer,
      sourceTopic: '', sourceConflict: '', requiredTerms: [], requiredObjects: [],
      requiredAction: '', affectedGroups: [], concreteNumbers: [], responsibilities: [],
      documentType: '', quotesVerbatim: [],
      parseError: true
    }
  };
}

return {
  json: {
    vorgangKey: base.vorgangKey,
    vorgangsnummer: base.vorgangsnummer,
    sourceTopic: safeStr(parsed.sourceTopic),
    sourceConflict: safeStr(parsed.sourceConflict),
    requiredTerms: asArr(parsed.requiredTerms),
    requiredObjects: asArr(parsed.requiredObjects),
    requiredAction: safeStr(parsed.requiredAction),
    affectedGroups: asArr(parsed.affectedGroups),
    concreteNumbers: asArr(parsed.concreteNumbers),
    responsibilities: asArr(parsed.responsibilities),
    documentType: safeStr(parsed.documentType),
    quotesVerbatim: asArr(parsed.quotesVerbatim),
    parseError: false
  }
};
